COMPONENT [screen-shake]: Screen shake with exponential decay: trigger with a power on impacts, apply as a canvas translate around all drawing
```js
const shake = { x: 0, y: 0, amt: 0 };
function triggerScreenShake(power) { shake.amt = Math.max(shake.amt, power); } // e.g. 6 small hit, 12 explosion
function updateShake(dt) {
  if (shake.amt > 0.1) {
    shake.x = (Math.random() - 0.5) * shake.amt;
    shake.y = (Math.random() - 0.5) * shake.amt;
    shake.amt *= Math.exp(-6 * dt);   // smooth decay
  } else { shake.x = 0; shake.y = 0; shake.amt = 0; }
}
// In draw(): wrap EVERYTHING between save/translate and restore:
//   ctx.save(); ctx.translate(shake.x, shake.y);
//   ...all game drawing...
//   ctx.restore();
```

COMPONENT [wave-spawner]: Timed enemy waves with per-wave count/interval, escalation by wave index, and wave-clear detection when all spawned are defeated.
```js
const Waves = { index: 0, timer: 0, spawned: 0, alive: 0, between: 3 };
function updateWaves(dt, def, spawnFn) {
  // def(i) -> {count, interval, type} or null when no more waves.
  const w = def(Waves.index); if (!w) return true;            // all clear
  Waves.timer += dt;
  if (Waves.spawned < w.count && Waves.timer >= w.interval) {
    Waves.timer = 0; Waves.spawned++; Waves.alive++; spawnFn(w.type, Waves.index);
  }
  if (Waves.spawned >= w.count && Waves.alive <= 0) {          // wave cleared
    Waves.index++; Waves.spawned = 0; Waves.timer = -Waves.between;  // brief pause
  }
  return false;
}
// On enemy death: Waves.alive--;   Expose state.wave = Waves.index + 1;
```
